$(function () {
  $("#recuperar_clave").click(function () {
    $("#panel-recuperar").css("display", "block");
    $("#panel-login").css("display", "none");
  });
  $("#btn-atras").click(function () {
    $("#panel-recuperar").css("display", "none");
    $("#panel-login").css("display", "block");
  });
  function validaciones(tipo, campo, nombre) {
    if (tipo == "vacio") {
      if (campo == null || campo.length == 0) {
        return "El campo " + nombre + " no puede estar vacio";
      } else {
        return true;
      }
    }

    if (tipo == "alfanumericos") {
      var exp_alfanume = /^[0-9a-zA-Z]+$/;
      if (!exp_alfanume.test(campo.trim())) {
        return "El campo " + nombre + " debe contener solo letras y numeros";
      } else {
        return true;
      }
    }

    if (tipo == "password") {
      var carac_pass = /^[\s\S]{6,30}$/;
      if (!carac_pass.test(campo.trim())) {
        return "El campos " + nombre + " debe contener minimo 6 digitos y maximo 30";
        //return mostrarError("El campo " + nombre + " debe contener minimo 6 digitos y maximo 30", msError);
      }

      var exp_pass = /^(?=.*[A-Za-z])(?=.*\d)([A-Za-z\d]|[^ ])/;
      if (!exp_pass.test(campo.trim())) {
        return "El campo " + nombre + " debe contener al menos 1 letra, un numero";
      } else {
        return true;
      }
    }
    if (tipo == "email") {
      var exp_email = /[\w-\.]{2,}@([\w-]{2,}\.)*([\w-]{2,}\.)[\w-]{2,4}/;
      if (!exp_email.test(campo.trim())) {
        return "El campo " + nombre + " debe ser un email valido";
      } else {
        return true;
      }
    }
  }
  function removerClaseserror(label, campo) {
    $(label).text("");
    $(campo).removeClass("errorClass");
  }
  function agregarClaseserror(label, campo, texto) {
    $(label).text(texto).css("color", "red");
    $(campo).addClass("errorClass");
  }
  $("#user_log").focusin(function () {
    removerClaseserror("#error_user_log", "#user_log");
  });
  $("#pass").focusin(function () {
    removerClaseserror("#error_pass", "#pass");
  });
  $("#correo").focusin(function () {
    removerClaseserror("#error_correo", "#correo");
  });

  $("#btn_recuperar").click(function () {
    correo = $("#correo").val();
    valid_correo = validaciones("email", correo, "Correo");
    if (valid_correo != true) {
      agregarClaseserror("#error_correo", "#correo", valid_correo);
    } else {
      removerClaseserror("#error_correo", "#correo");
    }
    return false;
  });
});
